/* CSS PART 1 OF 4 */

/* =========================================
   JOSH BROOKS CONSTRUCTION & RENOVATION
   Original design direction:
   Modern craftsmanship / Architectural editorial
   ========================================= */

/* 1. DESIGN TOKENS */

:root {
  color-scheme: light;

  /* Core palette */
  --color-ink: #202a30;
  --color-ink-soft: #35434a;
  --color-slate: #52636b;
  --color-muted: #78858a;

  --color-paper: #f6f5f0;
  --color-white: #ffffff;
  --color-surface: #eeede7;
  --color-border: #deded6;

  /* Warm construction-inspired accent */
  --color-accent: #c58b48;
  --color-accent-dark: #98672f;
  --color-accent-light: #e9d3b3;

  --color-success: #526d5b;
  --color-focus: #236ca3;

  /* Typography */
  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Helvetica, Arial, sans-serif;

  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-md: 1.125rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: 2rem;
  --font-size-3xl: clamp(2.5rem, 5vw, 4.5rem);
  --font-size-hero: clamp(3rem, 7vw, 6.5rem);

  --line-height-tight: 1.05;
  --line-height-heading: 1.2;
  --line-height-body: 1.7;

  --letter-spacing-tight: -0.045em;
  --letter-spacing-normal: 0;
  --letter-spacing-wide: 0.12em;

  /* Layout */
  --container-width: 1240px;
  --container-narrow: 820px;
  --page-gutter: clamp(1.25rem, 5vw, 5rem);

  --section-space: clamp(5rem, 10vw, 9rem);
  --section-space-small: clamp(3rem, 6vw, 5rem);

  --header-height: 84px;

  /* Borders and corners */
  --border-thin: 1px solid var(--color-border);
  --border-strong: 1px solid var(--color-ink);

  --radius-small: 3px;
  --radius-medium: 8px;
  --radius-large: 14px;
  --radius-pill: 999px;

  /* Shadows */
  --shadow-soft: 0 12px 40px rgba(32, 42, 48, 0.07);
  --shadow-medium: 0 20px 55px rgba(32, 42, 48, 0.13);

  /* Motion */
  --transition-fast: 180ms ease;
  --transition-normal: 300ms ease;
  --transition-slow: 500ms ease;

  /* Stacking */
  --z-base: 1;
  --z-header: 100;
  --z-overlay: 200;
}


/* 2. RESET AND GLOBAL FOUNDATIONS */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--header-height) + 24px);
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  min-width: 320px;
  margin: 0;
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  line-height: var(--line-height-body);
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body,
button,
input,
select,
textarea {
  font-family: var(--font-body);
}

img,
picture,
video,
canvas,
svg {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  color: inherit;
}

a {
  color: inherit;
  text-decoration: none;
}

ul,
ol {
  padding: 0;
  margin: 0;
  list-style: none;
}

h1,
h2,
h3,
h4,
h5,
h6,
p,
figure {
  margin: 0;
}

p + p {
  margin-top: 1rem;
}

::selection {
  color: var(--color-white);
  background: var(--color-ink);
}

:focus {
  outline: none;
}

:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 5px;
}

[hidden] {
  display: none !important;
}


/* 3. TYPOGRAPHY SYSTEM */

h1,
h2,
h3,
h4 {
  color: var(--color-ink);
  font-weight: 400;
}

h1,
h2 {
  font-family: var(--font-display);
  letter-spacing: var(--letter-spacing-tight);
}

h1 {
  font-size: var(--font-size-hero);
  line-height: var(--line-height-tight);
}

h2 {
  font-size: clamp(2.25rem, 4.5vw, 4rem);
  line-height: var(--line-height-heading);
}

h3 {
  font-size: clamp(1.25rem, 2vw, 1.65rem);
  line-height: 1.3;
  font-weight: 600;
  letter-spacing: -0.025em;
}

h4 {
  font-size: var(--font-size-md);
  line-height: 1.4;
  font-weight: 600;
}

p {
  color: var(--color-slate);
  font-size: var(--font-size-base);
  line-height: var(--line-height-body);
}

small {
  font-size: var(--font-size-sm);
}

strong {
  color: var(--color-ink);
  font-weight: 650;
}

em {
  font-family: var(--font-display);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.8rem;
  color: var(--color-accent-dark);
  font-size: var(--font-size-xs);
  font-weight: 700;
  letter-spacing: var(--letter-spacing-wide);
  line-height: 1.5;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 1px;
  background: currentColor;
  content: "";
  flex: 0 0 auto;
}

.section-heading {
  max-width: 760px;
}

.section-heading h2 {
  margin-top: 1.15rem;
}

.section-heading p {
  max-width: 610px;
  margin-top: 1.5rem;
  font-size: var(--font-size-md);
}

.text-accent {
  color: var(--color-accent-dark);
}

.text-light {
  color: var(--color-white);
}

.text-muted {
  color: var(--color-muted);
}

.text-small {
  font-size: var(--font-size-sm);
}


/* 4. PAGE GRID AND CONTAINERS */

.container {
  width: min(
    calc(100% - var(--page-gutter) * 2),
    var(--container-width)
  );
  margin-inline: auto;
}

.container-narrow {
  width: min(
    calc(100% - var(--page-gutter) * 2),
    var(--container-narrow)
  );
  margin-inline: auto;
}

.section {
  position: relative;
  padding-block: var(--section-space);
}

.section--compact {
  padding-block: var(--section-space-small);
}

.section--paper {
  background: var(--color-paper);
}

.section--white {
  background: var(--color-white);
}

.section--dark {
  background: var(--color-ink);
  color: var(--color-white);
}

.section--dark h2,
.section--dark h3,
.section--dark h4,
.section--dark strong {
  color: var(--color-white);
}

.section--dark p {
  color: rgba(255, 255, 255, 0.72);
}

.section--dark .eyebrow {
  color: var(--color-accent-light);
}


/* 5. SHARED LAYOUT UTILITIES */

.grid {
  display: grid;
  gap: 2rem;
}

.grid--two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid--three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.grid--four {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.split-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  align-items: center;
  gap: clamp(2.5rem, 6vw, 6rem);
}

.split-layout--wide {
  grid-template-columns: 1.15fr 0.85fr;
}

.split-layout--reverse {
  direction: rtl;
}

.split-layout--reverse > * {
  direction: ltr;
}

.stack {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.stack--tight {
  gap: 0.75rem;
}

.stack--loose {
  gap: 2.5rem;
}

.flex-between {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.align-center {
  align-items: center;
}

.justify-center {
  justify-content: center;
}

.center-text {
  text-align: center;
}

.max-width-text {
  max-width: 650px;
}

.mx-auto {
  margin-inline: auto;
}

.mt-auto {
  margin-top: auto;
}

.relative {
  position: relative;
}


/* 6. IMAGE FOUNDATIONS */

.image-frame {
  position: relative;
  overflow: hidden;
  background: var(--color-surface);
  border-radius: var(--radius-small);
}

.image-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-frame--landscape {
  aspect-ratio: 16 / 11;
}

.image-frame--portrait {
  aspect-ratio: 4 / 5;
}

.image-frame--wide {
  aspect-ratio: 16 / 9;
}

.image-frame--square {
  aspect-ratio: 1 / 1;
}


/* 7. DECORATIVE DETAILS */

.rule {
  width: 100%;
  height: 1px;
  background: var(--color-border);
}

.rule--dark {
  background: rgba(255, 255, 255, 0.2);
}

.accent-line {
  width: 54px;
  height: 3px;
  background: var(--color-accent);
}

.number-label {
  color: var(--color-accent-dark);
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-style: italic;
  font-variant-numeric: lining-nums;
}

.surface {
  background: var(--color-white);
  border: var(--border-thin);
  border-radius: var(--radius-medium);
}

.surface--soft {
  background: var(--color-surface);
  border: 0;
}


/* 8. ACCESSIBILITY AND MOTION */

.skip-link {
  position: absolute;
  z-index: 999;
  top: 12px;
  left: 12px;
  padding: 12px 18px;
  transform: translateY(-160%);
  background: var(--color-white);
  color: var(--color-ink);
  border: 2px solid var(--color-ink);
  border-radius: var(--radius-small);
  font-weight: 700;
}

.skip-link:focus {
  transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}


/* 9. RESPONSIVE GRID FOUNDATIONS */

@media (max-width: 900px) {
  :root {
    --header-height: 74px;
    --section-space: 6rem;
  }

  .grid--four {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .grid--three {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .split-layout,
  .split-layout--wide {
    grid-template-columns: 1fr;
    gap: 3rem;
  }

  .split-layout--reverse {
    direction: ltr;
  }
}

@media (max-width: 600px) {
  :root {
    --page-gutter: 1.25rem;
    --section-space: 4.5rem;
    --section-space-small: 3rem;
    --header-height: 68px;
  }

  body {
    font-size: 0.95rem;
  }

  .grid--two,
  .grid--three,
  .grid--four {
    grid-template-columns: 1fr;
  }

  .section-heading p {
    font-size: var(--font-size-base);
  }

  .flex-between {
    align-items: flex-start;
    flex-direction: column;
  }

  .stack--loose {
    gap: 1.75rem;
  }
}
