/* CSS PART 2 OF 4 */

/* =========================================
   HEADER, NAVIGATION, HERO & PRIMARY ACTION
   Josh Brooks Construction & Renovation Inc.
   ========================================= */


/* 1. SITE HEADER */

.site-header {
  position: sticky;
  z-index: var(--z-header);
  top: 0;
  width: 100%;
  min-height: var(--header-height);
  background: rgba(246, 245, 240, 0.97);
  border-bottom: 1px solid rgba(32, 42, 48, 0.1);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: var(--header-height);
  gap: 2rem;
}

.site-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.9rem;
  min-width: 0;
  color: var(--color-ink);
}

.site-brand img {
  width: 54px;
  height: 54px;
  flex: 0 0 auto;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  line-height: 1.2;
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.025em;
}

.brand-description {
  color: var(--color-muted);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}


/* 2. DESKTOP NAVIGATION */

.primary-navigation {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(1rem, 2vw, 2rem);
}

.primary-navigation > a,
.nav-dropdown-trigger {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding-block: 0.5rem;
  color: var(--color-ink-soft);
  background: transparent;
  border: 0;
  font-size: 0.8rem;
  font-weight: 650;
  letter-spacing: 0.015em;
  white-space: nowrap;
  cursor: pointer;
  transition: color var(--transition-fast);
}

.primary-navigation > a::after,
.nav-dropdown-trigger::after {
  position: absolute;
  right: 0;
  bottom: 5px;
  left: 0;
  height: 2px;
  background: var(--color-accent);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition-normal);
}

.primary-navigation > a:hover,
.nav-dropdown-trigger:hover {
  color: var(--color-accent-dark);
}

.primary-navigation > a:hover::after,
.nav-dropdown-trigger:hover::after,
.primary-navigation > a:focus-visible::after {
  transform: scaleX(1);
}

.nav-dropdown {
  position: relative;
}

.nav-dropdown-trigger {
  gap: 0.45rem;
}

.nav-dropdown-trigger::before {
  width: 6px;
  height: 6px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  content: "";
  transform: rotate(45deg) translateY(-2px);
}

.nav-dropdown-menu {
  position: absolute;
  top: calc(100% + 0.4rem);
  left: -1rem;
  display: flex;
  flex-direction: column;
  min-width: 220px;
  padding: 0.65rem;
  background: var(--color-white);
  border: var(--border-thin);
  border-radius: var(--radius-small);
  box-shadow: var(--shadow-medium);
  opacity: 0;
  visibility: hidden;
  transform: translateY(8px);
  transition:
    opacity var(--transition-fast),
    transform var(--transition-fast),
    visibility var(--transition-fast);
}

.nav-dropdown:hover .nav-dropdown-menu,
.nav-dropdown:focus-within .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.nav-dropdown-menu a {
  display: block;
  padding: 0.75rem 0.85rem;
  color: var(--color-slate);
  border-radius: var(--radius-small);
  font-size: 0.85rem;
  transition:
    color var(--transition-fast),
    background var(--transition-fast);
}

.nav-dropdown-menu a:hover,
.nav-dropdown-menu a:focus-visible {
  color: var(--color-ink);
  background: var(--color-surface);
}


/* 3. HEADER CONTACT ACTIONS */

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  flex: 0 0 auto;
}

.header-phone {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  color: var(--color-ink);
  font-size: 0.82rem;
  font-weight: 750;
  white-space: nowrap;
  transition: color var(--transition-fast);
}

.header-phone:hover {
  color: var(--color-accent-dark);
}

.header-phone-icon {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  background: var(--color-surface);
  border-radius: 50%;
  font-size: 0.9rem;
}


/* 4. BUTTON SYSTEM */

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 54px;
  padding: 0.9rem 1.6rem;
  border: 1px solid transparent;
  border-radius: var(--radius-small);
  font-size: 0.82rem;
  font-weight: 750;
  letter-spacing: 0.035em;
  line-height: 1.2;
  text-align: center;
  cursor: pointer;
  transition:
    color var(--transition-fast),
    background var(--transition-fast),
    border-color var(--transition-fast),
    box-shadow var(--transition-fast),
    transform var(--transition-fast);
}

.button:hover {
  transform: translateY(-2px);
}

.button:active {
  transform: translateY(0);
}

.button--primary {
  color: var(--color-white);
  background: var(--color-ink);
  border-color: var(--color-ink);
}

.button--primary:hover {
  color: var(--color-ink);
  background: var(--color-accent-light);
  border-color: var(--color-accent-light);
}

.button--accent {
  color: var(--color-ink);
  background: var(--color-accent);
  border-color: var(--color-accent);
}

.button--accent:hover {
  color: var(--color-white);
  background: var(--color-accent-dark);
  border-color: var(--color-accent-dark);
}

.button--outline {
  color: var(--color-ink);
  background: transparent;
  border-color: rgba(32, 42, 48, 0.45);
}

.button--outline:hover {
  color: var(--color-white);
  background: var(--color-ink);
  border-color: var(--color-ink);
}

.button--light {
  color: var(--color-ink);
  background: var(--color-white);
  border-color: var(--color-white);
}

.button--light:hover {
  color: var(--color-white);
  background: transparent;
}

.button--small {
  min-height: 44px;
  padding: 0.7rem 1.1rem;
  font-size: 0.76rem;
}

.button--large {
  min-height: 62px;
  padding-inline: 2rem;
}

.button--full {
  width: 100%;
}


/* 5. MOBILE NAVIGATION CONTROLS */

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  padding: 10px;
  place-items: center;
  background: transparent;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-small);
  cursor: pointer;
}

.menu-toggle-lines {
  display: flex;
  width: 21px;
  flex-direction: column;
  gap: 5px;
}

.menu-toggle-lines span {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--color-ink);
  transition:
    transform var(--transition-fast),
    opacity var(--transition-fast);
}

.menu-toggle[aria-expanded="true"] .menu-toggle-lines span:first-child {
  transform: translateY(7px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] .menu-toggle-lines span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] .menu-toggle-lines span:last-child {
  transform: translateY(-7px) rotate(-45deg);
}


/* 6. HERO SECTION */

.hero {
  position: relative;
  display: flex;
  min-height: min(780px, calc(100svh - var(--header-height)));
  align-items: center;
  overflow: hidden;
  background: var(--color-ink);
  color: var(--color-white);
}

.hero-media {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero-media::after {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(20, 29, 34, 0.94) 0%,
      rgba(20, 29, 34, 0.82) 38%,
      rgba(20, 29, 34, 0.37) 72%,
      rgba(20, 29, 34, 0.14) 100%
    ),
    linear-gradient(
      0deg,
      rgba(20, 29, 34, 0.38),
      transparent 50%
    );
  content: "";
}

.hero-content {
  position: relative;
  z-index: 1;
  width: 100%;
  padding-block: clamp(6rem, 12vw, 10rem);
}

.hero-copy {
  max-width: 790px;
}

.hero .eyebrow {
  color: var(--color-accent-light);
}

.hero h1 {
  max-width: 850px;
  margin-top: 1.5rem;
  color: var(--color-white);
}

.hero h1 span {
  color: var(--color-accent-light);
}

.hero-description {
  max-width: 600px;
  margin-top: 1.75rem;
  color: rgba(255, 255, 255, 0.83);
  font-size: clamp(1rem, 1.5vw, 1.2rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  margin-top: 2.25rem;
}

.hero-actions .button--primary {
  color: var(--color-ink);
  background: var(--color-accent);
  border-color: var(--color-accent);
}

.hero-actions .button--primary:hover {
  color: var(--color-ink);
  background: var(--color-accent-light);
  border-color: var(--color-accent-light);
}

.hero-actions .button--outline {
  color: var(--color-white);
  border-color: rgba(255, 255, 255, 0.65);
}

.hero-actions .button--outline:hover {
  color: var(--color-ink);
  background: var(--color-white);
  border-color: var(--color-white);
}


/* 7. HERO TRUST DETAILS */

.hero-details {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem 2.75rem;
  margin-top: clamp(3rem, 6vw, 5rem);
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.27);
}

.hero-detail {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.hero-detail strong {
  color: var(--color-white);
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 400;
}

.hero-detail span {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}


/* 8. HERO IMAGE CAPTION */

.hero-caption {
  position: absolute;
  right: var(--page-gutter);
  bottom: 1.5rem;
  z-index: 1;
  max-width: 260px;
  color: rgba(255, 255, 255, 0.75);
  font-size: 0.7rem;
  line-height: 1.5;
  text-align: right;
}


/* 9. CONTACT STRIP */

.contact-strip {
  position: relative;
  z-index: 2;
  background: var(--color-accent);
  color: var(--color-ink);
}

.contact-strip-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 92px;
  gap: 2rem;
}

.contact-strip-copy {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.contact-strip-copy strong {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 400;
}

.contact-strip-copy span {
  font-size: 0.8rem;
}

.contact-strip-links {
  display: flex;
  align-items: center;
  gap: 1.75rem;
}

.contact-strip-links a {
  color: var(--color-ink);
  font-size: 0.84rem;
  font-weight: 750;
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 4px;
  transition: text-decoration-color var(--transition-fast);
}

.contact-strip-links a:hover {
  text-decoration-color: currentColor;
}


/* 10. SECONDARY CONVERSION BANNER */

.conversion-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  padding: clamp(2rem, 5vw, 3.5rem);
  background: var(--color-ink);
  border-radius: var(--radius-medium);
  color: var(--color-white);
}

.conversion-banner h2 {
  max-width: 620px;
  color: var(--color-white);
  font-size: clamp(1.8rem, 3vw, 2.8rem);
}

.conversion-banner p {
  max-width: 540px;
  margin-top: 0.8rem;
  color: rgba(255, 255, 255, 0.72);
}

.conversion-banner .button {
  flex: 0 0 auto;
}


/* 11. RESPONSIVE HEADER AND NAVIGATION */

@media (max-width: 1100px) {
  .header-inner {
    gap: 1rem;
  }

  .primary-navigation {
    gap: 1rem;
  }

  .primary-navigation > a,
  .nav-dropdown-trigger {
    font-size: 0.74rem;
  }

  .header-phone {
    font-size: 0.75rem;
  }

  .site-brand img {
    width: 46px;
    height: 46px;
  }

  .brand-name {
    font-size: 0.94rem;
  }
}

@media (max-width: 900px) {
  .menu-toggle {
    display: grid;
    margin-left: auto;
  }

  .header-actions {
    display: none;
  }

  .primary-navigation {
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    display: none;
    align-items: stretch;
    flex-direction: column;
    gap: 0;
    padding: 0.75rem var(--page-gutter) 1.5rem;
    background: var(--color-paper);
    border-bottom: 1px solid var(--color-border);
    box-shadow: var(--shadow-soft);
  }

  .primary-navigation.is-open {
    display: flex;
  }

  .primary-navigation > a,
  .nav-dropdown-trigger {
    display: flex;
    width: 100%;
    min-height: 48px;
    justify-content: flex-start;
    padding: 0.8rem 0;
    border-bottom: 1px solid var(--color-border);
    font-size: 0.9rem;
  }

  .primary-navigation > a::after,
  .nav-dropdown-trigger::after {
    display: none;
  }

  .nav-dropdown {
    width: 100%;
  }

  .nav-dropdown-menu {
    position: static;
    display: none;
    min-width: 0;
    padding: 0.25rem 0 0.5rem 1rem;
    background: transparent;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    opacity: 1;
    visibility: visible;
    transform: none;
  }

  .nav-dropdown:hover .nav-dropdown-menu,
  .nav-dropdown:focus-within .nav-dropdown-menu {
    display: flex;
  }

  .nav-dropdown-menu a {
    min-height: 44px;
    padding-block: 0.65rem;
  }

  .hero {
    min-height: 680px;
  }

  .hero-media::after {
    background:
      linear-gradient(
        90deg,
        rgba(20, 29, 34, 0.91),
        rgba(20, 29, 34, 0.53)
      ),
      linear-gradient(
        0deg,
        rgba(20, 29, 34, 0.55),
        transparent
      );
  }
}


/* 12. RESPONSIVE HERO AND ACTIONS */

@media (max-width: 600px) {
